html:
{% set info = invoice_context(doc) %}
<style>
.iran-invoice { direction: rtl; font-family: Tahoma, sans-serif; color: #111; font-size: 10pt; }
.iran-invoice h2 { text-align: center; margin: 0 0 12px; }
.iran-invoice table { width: 100%; border-collapse: collapse; margin: 10px 0; }
.iran-invoice th, .iran-invoice td { border: 1px solid #555; padding: 6px; text-align: right; }
.iran-invoice thead { display: table-header-group; }
.iran-invoice tr { page-break-inside: avoid; }
.iran-invoice .number { direction: ltr; text-align: left; white-space: nowrap; }
.iran-invoice .totals { width: 55%; margin-right: auto; }
@media print { .iran-invoice { font-size: 9pt; } }
</style>
<div class="iran-invoice">
<h2>{{ "صورتحساب رسمی فروش" if doc.iran_official_invoice else "صورتحساب فروش" }}</h2>
<p>شماره: <b>{{ doc.name | e }}</b> — تاریخ: {{ info.jalali_date | e }} ({{ doc.posting_date | e }}) — ارز: {{ doc.currency | e }}</p>
{% if doc.docstatus == 0 %}<p><b>پیش‌نویس</b></p>{% elif doc.docstatus == 2 %}<p><b>باطل شده</b></p>{% endif %}
{% if doc.is_return %}<p>برگشت از فروش — مرجع: {{ (doc.return_against or '') | e }}</p>{% endif %}
<table>
{% for title, party in [('فروشنده', info.seller), ('خریدار', info.buyer)] %}
<tr><th>{{ title }}</th><td colspan="3">{{ party.display_name | e }}</td></tr>
<tr><td>شناسه ملی: {{ (party.national_id or '') | e }}</td><td>کد اقتصادی: {{ (party.economic_code or '') | e }}</td>
<td>شماره ثبت: {{ (party.registration_number or '') | e }}</td><td>کد پستی: {{ (party.postal_code or '') | e }}</td></tr>
{% endfor %}
</table>
{% if doc.company_address_display %}<p>نشانی فروشنده: {{ doc.company_address_display }}</p>{% endif %}
{% if doc.address_display %}<p>نشانی خریدار: {{ doc.address_display }}</p>{% endif %}
<table><thead><tr><th>ردیف</th><th>کالا / خدمت</th><th>واحد</th><th>تعداد</th><th>نرخ</th><th>مبلغ خالص</th></tr></thead><tbody>
{% for row in doc.items %}<tr><td>{{ loop.index }}</td><td>{{ row.item_code | e }} — {{ row.item_name | e }}</td>
<td>{{ row.uom | e }}</td><td class="number">{{ row.get_formatted('qty', doc) }}</td>
<td class="number">{{ row.get_formatted('rate', doc) }}</td><td class="number">{{ row.get_formatted('net_amount', doc) }}</td></tr>{% endfor %}
</tbody></table>
<table class="totals">
<tr><th>جمع خالص</th><td class="number">{{ doc.get_formatted('net_total') }}</td></tr>
{% for row in doc.taxes %}<tr><th>{{ row.description | e }}</th><td class="number">{{ row.get_formatted('tax_amount', doc) }}</td></tr>{% endfor %}
<tr><th>جمع مالیات و عوارض</th><td class="number">{{ doc.get_formatted('total_taxes_and_charges') }}</td></tr>
<tr><th>جمع کل</th><td class="number">{{ doc.get_formatted('grand_total') }}</td></tr>
{% if doc.rounding_adjustment %}<tr><th>تعدیل گرد کردن</th><td class="number">{{ doc.get_formatted('rounding_adjustment') }}</td></tr>
<tr><th>مبلغ نهایی</th><td class="number">{{ doc.get_formatted('rounded_total') }}</td></tr>{% endif %}
</table>
<table><tr><td style="height:65px;width:50%">مهر و امضای فروشنده</td><td>مهر و امضای خریدار</td></tr></table>
</div>
